package dev.impossibledragon;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import org.joml.Vector3f;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** One model family (dragon / dragonling / head) as generated by tools/build_packs.py into models.json. */
final class ModelDef {

    static final class Joint {
        final Vector3f pivot;
        final Vector3f axis;
        final String parent;
        final double bias, amp, speed, phase;
        /** "jaw" = driven by the vanilla dragon's own flap clock, so it opens exactly like the middle head's jaw */
        final String sync;

        Joint(JsonObject o) {
            pivot = vec(o.getAsJsonArray("pivot"));
            axis = vec(o.getAsJsonArray("axis"));
            JsonElement p = o.get("parent");
            parent = (p == null || p.isJsonNull()) ? null : p.getAsString();
            bias = o.get("bias").getAsDouble();
            amp = o.get("amp").getAsDouble();
            speed = o.get("speed").getAsDouble();
            phase = o.get("phase").getAsDouble();
            JsonElement sy = o.get("sync");
            sync = (sy == null || sy.isJsonNull()) ? null : sy.getAsString();
        }

        double angle(double t, double flapTime) {
            if ("jaw".equals(sync)) {
                // EnderDragonModel: jaw.xRot = (sin(flapTime * 2PI) + 1) * 0.2
                return (Math.sin(flapTime * (Math.PI * 2)) + 1.0) * 0.2;
            }
            return bias + amp * Math.sin(speed * t + phase);
        }
    }

    static final class Part {
        final String id;
        final int cmd;
        final Vector3f center;
        final float k;
        /** innermost joint first */
        final List<Joint> chain = new ArrayList<>();

        Part(JsonObject o, Map<String, Joint> joints) {
            id = o.get("id").getAsString();
            cmd = o.get("cmd").getAsInt();
            center = vec(o.getAsJsonArray("center"));
            k = o.get("k").getAsFloat();
            JsonElement j = o.get("joint");
            String name = (j == null || j.isJsonNull()) ? null : j.getAsString();
            int guard = 0;
            while (name != null && guard++ < 8) {
                Joint jt = joints.get(name);
                if (jt == null) break;
                chain.add(jt);
                name = jt.parent;
            }
        }
    }

    final List<Part> parts = new ArrayList<>();

    ModelDef(JsonObject family) {
        Map<String, Joint> joints = new HashMap<>();
        JsonObject jo = family.getAsJsonObject("joints");
        for (String key : jo.keySet()) joints.put(key, new Joint(jo.getAsJsonObject(key)));
        family.getAsJsonArray("parts").forEach(e -> parts.add(new Part(e.getAsJsonObject(), joints)));
    }

    private static Vector3f vec(com.google.gson.JsonArray a) {
        return new Vector3f(a.get(0).getAsFloat(), a.get(1).getAsFloat(), a.get(2).getAsFloat());
    }
}
